// 텍스트와 조사 종류를 받아서 적절한 조사를 붙이는 함수
function applyJosa(text, type) {
    let result;

    // 입력된 텍스트에서 괄호 안 내용 제거하고, 한글, 숫자, 영문자만 남김
    const i = text.replace(/\(.*\)/gi, "").replace(/[^가-힣a-z\d]/gi, "");

    // 조사 붙일 조건을 판단하기 위한 정규식 (예: 한글, 숫자, 특정 문자 조합 검사) (boolean)
    const condition = /[가-힣]$/.test(i) && (i.substr(-1).charCodeAt(0) - 44032) % 28 > 0 ||
                    /[가-힣]\d*[013678]$/.test(i) || 
                    /[a-z]\d*[1789]$/i.test(i) || 
                    /([clmnp]|[blnt](e)|[co](k)|[aeiou](t)|mb|ng|lert)$/i.test(i);

    // 적절한 조사 붙이는 함수
    function getJosa(n) {
        // 입력된 조사 종류에 따라 알맞은 조사 선택
        result = "이/가" === type ? n[0] :  // "이/가" 조사를 사용할 경우 첫 번째 조사 "이" 또는 "가"
                "을/를" === type ? n[1] :  // "을/를" 조사를 사용할 경우 두 번째 조사 "을" 또는 "를"
                "은/는" === type ? n[2] :  // "은/는" 조사를 사용할 경우 세 번째 조사 "은" 또는 "는"
                "와/과" === type ? n[3] :  // "와/과" 조사를 사용할 경우 네 번째 조사 "와" 또는 "과"
                "로/으로" === type ? n[4] : "";  // "로/으로" 조사를 사용할 경우 다섯 번째 조사 "로" 또는 "으로"
    }

    // 텍스트의 끝이 한글, 숫자, 또는 영문으로 끝나는 경우에 조사를 붙임
    if (/([가-힣]|\d|[a-z])$/i.test(i)) {
        // 조건에 맞는 조사 붙임
        condition ? getJosa(["이", "을", "은", "과", "으로"]) : getJosa(["가", "를", "는", "와", "로"]);
        
    } else {
        // 조건에 맞지 않으면 원형 조사 붙임
        getJosa(["이(가)", "을(를)", "은(는)", "와(과)", "로(으로)"]);
    }

    // 조사 붙인 텍스트 반환
    return text + result;
}